import{_ as r}from"./chunks/d1023f0cbf3345526378.CWOstTdw.js";import{_ as o,C as p,o as l,c as n,j as a,a as s,E as i,a6 as m}from"./chunks/framework.CnPv4DE1.js";const x=JSON.parse('{"title":"学习速度提升10倍的5个方法","description":"","frontmatter":{"title":"学习速度提升10倍的5个方法","originalTitle":"5 Ways To Learn 10x Faster","date":"2022-08-06","originalUrl":"https://thedankoe.com/letters/5-ways-to-learn-10x-faster/","minutes":11,"sourceHash":"18bc3ea317868db130feb86b01eccdfc1fbba74ddb8578d3538b6ee56de97cc0","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/5-ways-to-learn-10x-faster/"}]]},"headers":[],"relativePath":"letters/5-ways-to-learn-10x-faster.md","filePath":"letters/5-ways-to-learn-10x-faster.md"}'),h={name:"letters/5-ways-to-learn-10x-faster.md"};function c(d,e,f,b,_,u){const t=p("ArticleMeta");return l(),n("div",null,[e[0]||(e[0]=a("h1",{id:"学习速度提升10倍的5个方法",tabindex:"-1"},[s("学习速度提升10倍的5个方法 "),a("a",{class:"header-anchor",href:"#学习速度提升10倍的5个方法","aria-label":'Permalink to "学习速度提升10倍的5个方法"'},"​")],-1)),i(t),e[1]||(e[1]=m('<p>我真的是听烦了人们用“样样通，样样松”（jack of all trades, master of none）这句俗话来为自己的自我设限找借口。这种观念不仅在在线商业或创作者（creator）圈子里根深蒂固，在整个生活中也是如此。想找份更好的工作？那就去精通那份工作所需的核心技能（而不是去掌握为了真正精通这项技能所必需的几十种其他技能、特质和行为）。正如你所见，我是凡事强调整体方法的拥趸。无论头脑、身体、灵魂，还是商业。</p><p>学习——或者说精通——生活中的一个新领域需要花费10000小时的时代已经过去了。当你彻底看穿这个统计数据时，就会发现它根本说不通。如果不去挑战这种集体信念，你就会封闭自己的大脑，屏蔽它本可以拥有的无限潜力。</p><blockquote><p>我不是什么样样通样样松的人；我是样样精通的大师。只要我想，我不觉得有什么是我做不到的。——埃维尔·克尼维尔（Evel Knievel）</p></blockquote><p>样样通，样样精。任何其他的思维方式都是自我设限的，它会渗入你的内心，像提线木偶大师一样玩弄你的情绪。</p><p>让我们以列奥纳多·达·芬奇（Leonardo Da Vinci）为例。里奥（Leo）——我们就这么叫他——是一位建筑师、雕塑家、画家，并被整个<em>世界</em>公认为文艺复兴时期最伟大的艺术家。说什么财富都在细分领域（niches）里，我可去他妈的吧。</p><p>罗根（Rogan）？甘比诺（Gambino）？马斯克（Musk）？</p><p><em>看起来这</em> <em>一切</em> <em>的关键在于精通万物，并将这种精通倾注于人生中的一个宏大目标。</em></p><h2 id="模糊感知的危险" tabindex="-1">模糊感知的危险 <a class="header-anchor" href="#模糊感知的危险" aria-label="Permalink to &quot;模糊感知的危险&quot;">​</a></h2><p>几周前，我们讨论了专注背后的深度，以及它并不全关乎深度工作（deep work）——它关乎你生活的方方面面。对我来说，专注可以是“有序意识”的同义词，这与导致“心理熵”的混乱意识完全相反，或者说，如果<em>不</em>专注，大脑就会倾向于失序。这就是确定性与不确定性之间的区别。是对你人生结果的掌控感还是绝望感。这可以说是幸福的关键。是时候升级我们专注的工具了。</p><p>把你个人的视角——或者说世界观——想象成一台单反相机。就是那些高级摄影师用的那种。相机本身有各种各样的设置和<em>程序</em>，让它们能够<em>看见</em>眼前的世界。这些相机允许你安装不同的镜头，从而获得不同的焦距和进光量。这些相机的许多功能还有“自动”和“手动”设置，但让我们结合对焦（专注）来谈谈。</p><p>当你的镜头模糊时，你看不清模糊的另一边是什么，你只能去猜测。你只能给自己编一个关于另一边有什么的故事。这就是感知。</p><p>在现实中，什么构成了我们的世界观——或者说视角？我们的信念、偏见、目标、价值观、愿景，以及其他所有被编入我们大脑的东西。信念、偏见等本身并不是问题。缺乏选择和意识才是问题所在。当处于无意识状态时——或者当我们的相机被设定为“自动”模式时——生存本能就会介入。</p><blockquote><p>“除非你让无意识变得有意识，否则它将主导你的人生，而你将其称为命运。”——卡尔·荣格（C.G. Jung）</p></blockquote><p>生存是我们日常生活的一部分，也是人类心理不可避免的功能，除非我们进化到超越它（？）。但当这些生存机制处于无意识状态时，我们到底在努力从什么之中生存下来？是从自我的概念中。意思是，我们依附于这些信念和偏见，并表现得仿佛我们就是它们。它们成为了我们身份认同的一部分。如果仅仅是你对健美的无意识依附感到了他人意见的威胁，你的关注点就会收缩，你的感知就会模糊。如果你对自己变得肌肉发达且皮肤古铜色的认同感受到威胁，你就会戴着生存岌岌可危的滤镜来感知世界。</p><p>这是一个意识到你的阴影并通过接纳和行为改变将其整合的终生过程，但这里有一个更大的教训：</p><p>当你的感知模糊时，你无法看清世界的<em>本来面目</em>。你将会错过生活本身这个学习的过程。</p><p>这是关于学习的，而意识到你不准确的感知，是你敞开心扉<em>去</em>学习的第一步。我相信我们会比现在更深入地探讨这个话题，但我感觉有必要先引起你的注意。</p><p>Koe的信中途提醒：<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以仅花5美元加入现代精通（Modern Mastery）。</a> 里面有什么？180多项经过验证的策略和个性化帮助，助你在生活和一人企业（one-person business）所有权上取得成功。</p><h2 id="向未知敞开心扉" tabindex="-1">向未知敞开心扉 <a class="header-anchor" href="#向未知敞开心扉" aria-label="Permalink to &quot;向未知敞开心扉&quot;">​</a></h2><p>带着模糊的感知，你会以一种机械、自动的方式评判和臆断周围的世界。带着清晰的感知，你则会以一种开放、有意识的方式进行观察和辨别。这就是这一切要传达的信息。如果你正试图学习商业，却因为与金钱有着糟糕、执念的关系，从而把注意力都集中在了商业中错误的地方……你就会抓破脑袋也想不通，为什么别人只有你一半的脑子，却能取得你两倍的进展。</p><p><img src="'+r+'" alt=""></p><p>我们以前多次讨论过未知的概念——那片拥有无限潜力的土地。这次也不例外。在当前的语境下，“未知”就是看清现实的本来面目。也就是说，对由于我们条件反射式的感知而导致日常意识遗漏的事物保持开放态度。这远超出了清理你自身镜头的范畴。这意味着你要能完全丢掉你的镜头，并对透过任何镜头去观看保持开放态度。有些人称之为同理心，我不想把事情搞复杂。在这里我们只是先试着保持开放。在试图采用他人视角的同又带着预设和评判，这似乎有违初衷。对当下发生的时刻保持开放吧，因为它就是如此，一场正在发生的事。</p><p>感知是选择性的。现在，想一想，你正在关注什么？屏幕上的这些字。但是什么让这些字<em>存在</em>呢？是它们背后的留白。就像一首歌是一系列声音的组合，但如果没有沉默的停顿，没有高音到低音的转换，没有慢节奏到快节奏的过渡，那它就不成其为一首歌……它只会是一声长长的尖叫。宇宙（Universe）也是如此。Uni = 一。Verse = 歌。</p><p>让我们付诸实践。</p><h2 id="元技能中的元技能" tabindex="-1">元技能中的元技能 <a class="header-anchor" href="#元技能中的元技能" aria-label="Permalink to &quot;元技能中的元技能&quot;">​</a></h2><p>学习是人类最基础的驱动力。我们从出生的那一秒起在做什么？学习。不然我们是怎么走到今天这个位置的？问题在于，我们被训练成了只看到一种单向度的生活方式。一种没有深度的肤浅存在。学这个，忽略那个。这样写，别那样写。追求这些目标，别追求你自己的。按我说的做，别按你说的做。</p><p>这导致了人类意识本身的极化。低级意识，高度无意识。在你的眼皮底下到底发生了什么，它又是如何阻碍你充分体验生活的？我们在这里采取的是一种非常宽泛的学习方法。生活就是我们的语境。但就像我讨论的大多数反映普遍规律的事物一样，它可以应用于任何维度。无论宏观还是微观。</p><p>以下是在你选择的任何现实中——个人的、文化的、社交的、宇宙的、情境的、对话的……任何领域——让你的学习提升10倍的5个步骤。</p><h3 id="_1-敞开你的大脑" tabindex="-1">1) 敞开你的大脑 <a class="header-anchor" href="#_1-敞开你的大脑" aria-label="Permalink to &quot;1) 敞开你的大脑&quot;">​</a></h3><p>这是理所当然的。如果你的大脑对学习本身都是封闭的，你还怎么学？当然，就像生活中任何美好的事物一样，这需要时间和练习。</p><p>我喜欢从社交媒体评论区的角度来思考这个问题。当一个拥有大量粉丝的人发了一篇帖子——不管内容是什么——评论通常会分为四大阵营：</p><ol><li>出于好奇而提问的人（心态开放）</li><li>根据自己的主观感知做出反应，看不透字面背后含义的人（心态封闭）</li><li>为了引流吸粉而回复的人（搞商业的）</li><li>给予鼓励或者只是回复一个表情符号的人（好人）</li></ol><p>第一种人对学习抱有开放态度。然而这会导致我们在第二点中要讨论的另一个问题。第二种人，由于缺乏自我意识以及一种令人费解的不想让自己好过的欲望，只看到他们眼见的，并用他们<em>所知</em>的那点东西来挑起争论。</p><p>我没必要告诉你这其中的问题所在。如果我告诉你，作为一个一人企业你可以赚到100万美元，你的反应是什么？是不是觉得“不可能”，因为你还从未接触过那种潜在的现实？符合逻辑的解决方案难道是永远对此封闭心智，然后躲在你把自己困住的舒适现实中吗？</p><p>这是在玩社交媒体时一件真正让我心烦的事（我正在努力克制这种情绪），但是如果不是为了充分利用社交媒体或生活，你还上网或活着干嘛呢？反思一下，我一直以来的目标之一就是证明别人错了。不管是好是坏，这促使我创作了有深度的时事通讯、课程和其他内容，因为我无法停止学习如何证明那些具有局限性的视角（以及我自己）是错的。</p><h3 id="_2-环境沉浸" tabindex="-1">2) 环境沉浸 <a class="header-anchor" href="#_2-环境沉浸" aria-label="Permalink to &quot;2) 环境沉浸&quot;">​</a></h3><p>当你对学习保持开放时，依赖任何特定的某个人为你提供所有的材料将是非常愚蠢的。还是以社交媒体为例，让我们想象一下有人发了一篇关于如何练出六块腹肌的科普贴。你已经能听到那种封闭的心态和自我设限的信念了。</p><p><em>“笑死，你以为所有人都能随便减肥吗？？？”</em></p><p><em>“间歇性断食？太弱智了吧，我们吃早餐都吃了几百年了！”</em></p><p><em>“生牛肝是地球上营养最密集的食物？哇哦，反正我根本不在乎。”</em></p><p>虽然我与这些事情并没有什么利益瓜葛（对于那些想知道我是不是还在吃生牛肝的人，答案是没有了），但对哪怕一件事封闭你的头脑，也会阻断你的大脑向其他能通往<em>或许</em>有助于创造更好未来的道路延展。以间歇性断食为例——对它敞开思维，能给你一个新的视角去进一步拓宽你的头脑。通过收集不同的视角，你就能把各个点连接起来，创造出完美为你量身定制的健康方案。</p><p>那些在看到帖子后愿意改善健康状况的人可以走以下两条路线之一：</p><ol><li>开始向创作者（creator）索要所有的答案，指望一个有自己事情要忙的人能给你写下堪比5本书的信息量</li><li>把它当作自己的责任，在一个能改善自己生活的领域去自我教育。</li></ol><p>在第二种情况下，环境沉浸就是答案。本质上，这意味着控制或<a href="https://thedankoe.com/how-to-master-your-focus/" target="_blank" rel="noreferrer">框定你的专注</a>，让自己暴露在与期望结果相关的信息中。关注那些提供不同视角的社交媒体账号。买书，听播客，和你那些狂热追求健康的朋友交流，报名上课，或者在你的能力范围内做任何能让你沉浸在这种信息量看似会让你过载的环境中的事。</p><p>为了防止信息过载，练习抽离和批判性思维。不要把任何建议奉为圭臬。是的，甚至也包括我的。我只不过是无限宇宙中的一个视角。</p><h3 id="_3-默默观察" tabindex="-1">3) 默默观察 <a class="header-anchor" href="#_3-默默观察" aria-label="Permalink to &quot;3) 默默观察&quot;">​</a></h3><p>我昨天下午刚回到亚利桑那州。连续两天每天开10个小时的车之后，我显然得补补落下的步数，所以我散了大约2个小时的步去探索这座城市。商店的新奇感，再加上我想弄清楚自己日常想去哪散步的意图，让我学得相当快。</p><p>静静地观察在于<em>保持</em>你的头脑对学习敞开。当你觉得自己已经学会了一切时，很容易就会“封闭”起来。我们的头脑很狡猾。它喜欢死死抓住那些最能满足自我的想法。</p><p>如果我在网上听到一个完美地向我推销的饮食建议，我很容易就会把它奉为圭臬，去尝试一下，看到不错的结果，然后觉得那是适合所有人的最佳选择——但实际上，这甚至可能并不是最适合<em>我</em>的选择<em>！</em></p><h3 id="_4-将点连成线" tabindex="-1">4) 将点连成线 <a class="header-anchor" href="#_4-将点连成线" aria-label="Permalink to &quot;4) 将点连成线&quot;">​</a></h3><p>使用法则。</p><p>“如果你不用它，你就会失去它。”</p><p>所有人都在声嘶力竭地冲着你大喊大叫，让你去采取行动，这是有原因的。你问为什么？</p><p>因为如果你不行动，你<strong>根本学不到任何东西</strong>。如果你不通过亲身经历来巩固你的发现并将其教给别人，你就是在散播谎言。你只是在鹦鹉学舌别人说的话。你是在像机器人一样生活，给着你自己都没有践行过的建议。这与其说是在坑那些听你建议的人，不如说是在坑你自己。</p><p>采取行动的方式不仅仅是身体层面的。你可以写作、思考、冥想，并根据你学到的内容来运用其他方法。</p><p>当你运用（Use）你学到的东西时，你会被迫用你自己的方式来做。在取得突破之前，你会面临阻力。当一切都“融会贯通”，并且你迎来那个“啊哈！”时刻时，你会感觉到大脑里的多巴胺水平在飙升。你会感受到那种兴奋。</p><p>只要你沉浸在一个环境中并不断运用你学到的东西，这种现象就会持续发生。这就是为什么我写这么多东西——因为我享受消费那些我想深入学习的信息。我把我的头脑、身体和生意当成一个科学项目。我执行得很快，并从中收获了神经生物学层面的好处。</p><h3 id="_5-积累经验" tabindex="-1">5) 积累经验 <a class="header-anchor" href="#_5-积累经验" aria-label="Permalink to &quot;5) 积累经验&quot;">​</a></h3><p>带着开放的心态、有利的环境、清晰的观察，以及将各个点连成线的过程——你的学习将会产生复利。当你不死死抓住某些特定信念不放时，你的学习速度会快得令人难以置信。</p><blockquote><p>复杂性是两种广泛的心理过程共同作用的结果：分化（differentiation）与整合（integration）。分化意味着一种走向独特性、将自己与他人区分开来的运动。整合则恰恰相反：它指的是与他人、与超越自我的思想和实体的结合。一个复杂的自我，就是成功地将这两种截然相反的倾向结合起来的自我。 —— 米哈里·契克森米哈赖（Mihaly Csikszentmihalyi）</p></blockquote><p>随着时间的推移，你的人生经验值（XP）会不断增加。你的自我会变得更加复杂。你会开始更加享受生活，因为你不再觉得有必要去捍卫自己的观点——因为你知道世界上存在着无穷无尽的其他视角。死死抓住其中一个视角不放，正是痛苦的根源。</p><p>—— 丹·柯（Dan Koe）</p><p><strong>本周动态</strong></p><p>我刚回到亚利桑那州（AZ），很快就会恢复 YouTube 的更新日程。我为这份新闻通讯以及整体的其他内容策划了一些非常酷的东西。</p><p>在 Modern Mastery 社群内部，个人品牌顾问萨娜（Sana）发布了一套框架，介绍了她是如何引导客户打磨他们自己的故事的。非常多的创作者（creator）想要（也需要）写下他们自己的故事。她向你展示了如何做才能达到最大的效果。你的故事就是你最强大的营销工具。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以在这里花5美元加入。</a></p><p>最后一件事，我将在下周的 Koe Letter 中开启一款新产品——《两小时写作者》（The 2 Hour Writer）的预售。如果你想学习我是如何在不到 2 小时的时间内批量完成我的新闻通讯、推文以及推文串的写作（并同时将其内容复用到所有平台），请密切关注。</p><hr><p><a href="/en/letters/5-ways-to-learn-10x-faster">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',69))])}const g=o(h,[["render",c]]);export{x as __pageData,g as default};
